create table if not exists public.profile_preferences(user_id uuid primary key references auth.users(id) on delete cascade,profile_visibility text not null default 'community',show_activity boolean not null default true,show_checkins boolean not null default true,show_reviews boolean not null default true,allow_followers boolean not null default true,discoverable boolean not null default true,preferred_units text not null default 'imperial',home_region text,updated_at timestamptz not null default now());alter table public.profile_preferences enable row level security;drop policy if exists profile_preferences_owner_all on public.profile_preferences;create policy profile_preferences_owner_all on public.profile_preferences for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create or replace function public.get_my_profile_preferences() returns public.profile_preferences language sql stable security invoker set search_path=public,pg_temp as $$select * from public.profile_preferences where user_id=auth.uid()$$;create or replace function public.update_my_profile_preferences(p_preferences jsonb) returns public.profile_preferences language plpgsql security invoker set search_path=public,pg_temp as $$declare v public.profile_preferences;begin insert into public.profile_preferences(user_id) values(auth.uid()) on conflict(user_id) do nothing;update public.profile_preferences set profile_visibility=coalesce(nullif(p_preferences->>'profile_visibility',''),profile_visibility),show_activity=coalesce((p_preferences->>'show_activity')::boolean,show_activity),show_checkins=coalesce((p_preferences->>'show_checkins')::boolean,show_checkins),show_reviews=coalesce((p_preferences->>'show_reviews')::boolean,show_reviews),allow_followers=coalesce((p_preferences->>'allow_followers')::boolean,allow_followers),discoverable=coalesce((p_preferences->>'discoverable')::boolean,discoverable),preferred_units=coalesce(nullif(p_preferences->>'preferred_units',''),preferred_units),home_region=coalesce(nullif(p_preferences->>'home_region',''),home_region),updated_at=now() where user_id=auth.uid() returning * into v;return v;end$$;grant execute on function public.get_my_profile_preferences() to authenticated;grant execute on function public.update_my_profile_preferences(jsonb) to authenticated;
